function art(h,v){const u=190+(Math.round(h)+v*13)%40;return"data:image/svg+xml;utf8,"+encodeURIComponent(`<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 400 260'><defs><linearGradient id='g' x1='0' y1='0' x2='1' y2='1'><stop offset='0' stop-color='hsl(${u},28%,62%)'/><stop offset='1' stop-color='hsl(${u+20},30%,80%)'/></linearGradient></defs><rect width='400' height='260' fill='url(#g)'/><g transform='translate(164 94) scale(3)' fill='none' stroke='white' stroke-opacity='.75' stroke-width='1.4' stroke-linecap='round' stroke-linejoin='round'><path d='M3 11l9-8 9 8'/><path d='M5 10v10h14V10'/><path d='M10 20v-6h4v6'/></g></svg>`)}
let S={listings:[],favs:[],gallery:[],me:null,reqs:[],msgs:[],mine:[],stats:{landlords:0,tenants:0},popularAreas:{},featuredAreas:{},featuredCounty:"Nairobi",analytics:null,analyticsDays:30,cfg:{payments:{tenant:{},landlord:{}},products:[],pesapal:false,me:null},bookings:[],reqLocked:false,adminPay:null,adminProducts:[],adminPayments:null};
async function api(p,o={}){const h={},t=localStorage.getItem("nf_t");if(t)h.Authorization="Bearer "+t;if(o.json){h["Content-Type"]="application/json";o={...o,body:JSON.stringify(o.json)}}
const r=await fetch("/api"+p,{...o,headers:h}),d=await r.json().catch(()=>({}));if(!r.ok)throw Object.assign(new Error(d.error||"Request failed"),{status:r.status,need:d.need,role:d.role,needLogin:d.needLogin});return d}
function prep(l){l.id=String(l.id);l.real=l.imgs.slice();if(!l.imgs.length)l.imgs=[0,1,2].map(i=>art(i*40+l.id.length*30,i));l.at=+l.at;return l}
async function loadListings(){S.listings=(await api("/listings")).listings.map(prep)}
function closeMenu(){document.body.classList.remove("menu")}
function toast(m){const t=document.createElement("div");t.className="toast";t.textContent=m;document.body.append(t);setTimeout(()=>t.remove(),2400)}
function theme(){const r=document.documentElement;r.dataset.theme=(r.dataset.theme||(matchMedia("(prefers-color-scheme:dark)").matches?"dark":"light"))=="dark"?"light":"dark"}
let installPromptEvent=null;
function isStandalone(){return matchMedia("(display-mode:standalone)").matches||navigator.standalone===true}
function updateInstallButton(){const b=$("#install-app");if(!b)return;const mobile=/Android|iPhone|iPad|iPod/i.test(navigator.userAgent)||(navigator.platform==="MacIntel"&&navigator.maxTouchPoints>1);b.hidden=!(mobile&&matchMedia("(max-width:800px)").matches&&!isStandalone())}
function openInstallPopup(){const ios=/iPhone|iPad|iPod/i.test(navigator.userAgent)||(navigator.platform==="MacIntel"&&navigator.maxTouchPoints>1);const android=/Android/i.test(navigator.userAgent);
const instructions=ios?"Open this page in Safari, tap Share, then choose “Add to Home Screen” to install NyumbaFind.":android?"Use the Install NyumbaFind button below, or open your browser menu and choose “Install app” or “Add to Home screen”.":"Open this site in your phone’s browser and choose “Install app” or “Add to Home screen” from its menu.";
const m=modal(`<h2 id="install-title">Get NyumbaFind on your phone</h2><p>${instructions}</p>${installPromptEvent?'<button id="install-now" class="btn">Install NyumbaFind</button>':""}`);
m.querySelector(".box").setAttribute("role","dialog");m.querySelector(".box").setAttribute("aria-modal","true");m.querySelector(".box").setAttribute("aria-labelledby","install-title");
const b=m.querySelector("#install-now");if(b)b.onclick=async()=>{const prompt=installPromptEvent;if(!prompt)return;installPromptEvent=null;b.disabled=true;try{await prompt.prompt();const choice=await prompt.userChoice;if(choice.outcome==="accepted"){m.remove();toast("NyumbaFind installed")}else toast("Installation was cancelled")}catch(e){toast("Could not start installation. Use your browser menu instead.")}updateInstallButton()}}
window.addEventListener("beforeinstallprompt",e=>{e.preventDefault();installPromptEvent=e;updateInstallButton()});
window.addEventListener("appinstalled",()=>{installPromptEvent=null;updateInstallButton()});
window.addEventListener("resize",updateInstallButton);
updateInstallButton();
let view="home",F={q:"",county:"Nairobi",area:"",type:"",min:"",max:"",feat:[],sort:"new",map:false},here=null;
function go(v){closeMenu();view=v;render();scrollTo(0,0)}
function nav(){const m=S.me,b=(v,t)=>`<button class="btn g tab ${view==v?"on":""}" onclick="go('${v}')">${t}</button> `;
$("#nav").innerHTML=b("home","Home")+b("browse","Browse")+b("about","About")+b("contact","Contact")+(m?b("favs","Favorites ("+(S.favs).length+")"):"")+(m?b("bookings",m.role=="tenant"?"My trips":"Bookings"):"")+(m&&m.role!="tenant"?b("dash",m.role=="admin"?"Admin":"My listings"):"")+(m?`<span class="sub">${esc(m.name)} · ${m.role}</span> <button class="btn g" onclick="logout()">Logout</button>`:`<button class="btn" onclick="authBox()">Login / Sign up</button>`)}
function logout(){localStorage.removeItem("nf_t");S.me=null;S.favs=[];S.cfg.me=null;go("home");loadListings().then(()=>{if(view=="home"||view=="browse")render()});loadConfig();toast("Logged out")}
function render(){nav();$("#hero").innerHTML="";({home,about,contact,browse,favs,dash,bookings})[view]()}
function filt(){return S.listings.filter(l=>l.vacant&&(!F.q||(l.title+l.desc+l.area).toLowerCase().includes(F.q.toLowerCase()))&&(!F.county||countyForArea(l.area)==F.county)&&(!F.area||l.area==F.area)&&(!F.type||l.type==F.type)&&(!F.min||l.price>=+F.min)&&(!F.max||l.price<=+F.max)&&(!F.mode||l.mode==F.mode)&&(!F.avail||F.avail.includes(l.id))&&F.feat.every(f=>l.feats.includes(f)))}
function dist(l){if(!here)return null;const R=6371,r=x=>x*Math.PI/180,a=Math.sin(r(l.lat-here[0])/2)**2+Math.cos(r(here[0]))*Math.cos(r(l.lat))*Math.sin(r(l.lng-here[1])/2)**2;return 2*R*Math.asin(Math.sqrt(a))}
const payOn=(role,feat)=>{const p=(S.cfg.payments||{})[role]||{};return !!(p.enabled&&p[feat])};
const priceTxt=l=>KES(l.price)+(l.mode=="stay"?"/night":"/month");
function card(l,i){const f=S.me&&(S.favs).includes(l.id),d=dist(l),b=l.boost||{};return`<div class="card ${b.badge?"boosted":""}" style="animation-delay:${i*50}ms" onclick="detail('${l.id}')"><div class="imgw"><img src="${l.imgs[0]}" data-l="${l.id}" alt=""><span class="tag">${esc(l.type)}${l.mode=="stay"?" · Stay":""}</span>${b.badge?`<span class="tagf">${I('star',12)} Featured</span>`:""}<button class="fav ${f?"on":""}" onclick="event.stopPropagation();fav('${l.id}')">${I('heart')}</button></div><div class="b"><div class="price">${KES(l.price)}<span class="sub">${l.mode=="stay"?" / night":"/month"}</span></div><b>${esc(l.title)}</b><div class="sub">${I('pin',14)} ${esc(l.area)}${d!=null?" · "+d.toFixed(1)+" km away":""}${l.mode=="stay"?" · up to "+l.maxGuests+" guests":""}</div><div class="sub">${l.locked?I('lock',13)+" Contact locked":l.feats.slice(0,3).map(esc).join(" · ")}</div></div></div>`}
function mapHtml(ls,id,click){const roads=`<svg viewBox="0 0 100 100" preserveAspectRatio="none"><path d="M0 60 C30 50 50 70 100 40" stroke="#fff" stroke-width="1.4" fill="none"/><path d="M45 0 C50 40 40 70 55 100" stroke="#fff" stroke-width="1.4" fill="none"/><path d="M0 20 L100 85" stroke="#ffffffaa" stroke-width=".8" fill="none"/></svg>`,county=ls[0]?.county||countyForArea(ls[0]?.area)||F.county||"Nairobi",bounds=MAP_BOUNDS[county]||BB;const P=(la,ln)=>`left:${(ln-bounds.ln[0])/(bounds.ln[1]-bounds.ln[0])*100}%;top:${(bounds.la[1]-la)/(bounds.la[1]-bounds.la[0])*100}%`;
return`<div class="map" id="${id}" ${click?`onclick="pick(event)"`:""}>${roads}${Object.entries(AREAS).filter(([name])=>countyForArea(name)===county).map(([n,c])=>`<span class="lbl" style="${P(c[0],c[1])}">${n}</span>`).join("")}${ls.map(l=>`<span class="pin" style="${P(l.lat,l.lng)}" title="${esc(l.title)}" ${click?"":`onclick="event.stopPropagation();detail('${l.id}')"`}>${I('pin',30)}</span>`).join("")}${here&&!click?`<span class="pin me" style="${P(here[0],here[1])}"></span>`:""}</div>`}
function browse(){const ls=filt();const d=l=>dist(l)??0;ls.sort((a,b)=>F.sort=="lo"?a.price-b.price:F.sort=="hi"?b.price-a.price:F.sort=="near"?d(a)-d(b):b.at-a.at);if(F.sort!="near"){const pin=ls.filter(l=>l.boost&&l.boost.pin),rest=ls.filter(l=>!(l.boost&&l.boost.pin));ls.splice(0,ls.length,...pin,...rest)}
$("#app").innerHTML=`<div class="hero"><h1>Find a home you'll love</h1><p>Browse vacant houses in ${esc(F.county||"Nairobi")}.</p></div>
<div class="filters"><input id="fq" placeholder="Search…" value="${esc(F.q)}"><select id="fc">${countyOptions(F.county||"Nairobi")}</select><select id="fa"><option value="">All locations</option>${areaOptions(F.county||"Nairobi",F.area)}</select><select id="ft"><option value="">All types</option>${TYPES.map(a=>`<option ${F.type==a?"selected":""}>${a}</option>`).join("")}</select><input id="fmin" type="number" placeholder="Min price" value="${F.min}"><input id="fmax" type="number" placeholder="Max price" value="${F.max}"><select id="fs"><option value="new">Newest</option><option value="lo" ${F.sort=="lo"?"selected":""}>Price: low–high</option><option value="hi" ${F.sort=="hi"?"selected":""}>Price: high–low</option><option value="near" ${F.sort=="near"?"selected":""}>Nearest to me</option></select></div>
<div class="chips"><span class="chip ${!F.mode?"on":""}" onclick="setMode('')">All</span><span class="chip ${F.mode=="rent"?"on":""}" onclick="setMode('rent')">Monthly rentals</span><span class="chip ${F.mode=="stay"?"on":""}" onclick="setMode('stay')">${I("calendar",14)} Short stays</span></div>${F.mode=="stay"?stayBar():""}
<div class="chips">${FEATS.map(f=>`<span class="chip ${F.feat.includes(f)?"on":""}" onclick="tf('${f}')">${f}</span>`).join("")}</div>
<div class="bar"><b>${ls.length} vacant house${ls.length==1?"":"s"}</b><div><button class="btn g" onclick="locate()">${I('locate')} Use my location</button> <button class="btn t" onclick="F.map=!F.map;browse()">${F.map?"Hide map":I('map')+" Show on map"}</button> <button class="btn g" onclick="F={q:'',county:'Nairobi',area:'',type:'',min:'',max:'',feat:[],sort:'new',map:F.map};browse()">Reset</button></div></div>
${F.map?mapHtml(ls,"bm")+"<br>":""}<div class="grid">${ls.map(card).join("")||'<div class="empty">No houses match. Try loosening the filters.</div>'}</div>`;
const bind=(i,k)=>$(i).oninput=e=>{F[k]=e.target.value;clearTimeout(bind.t);bind.t=setTimeout(()=>{browse();const el=$(i);if(el)el.focus()},350)};
bind("#fq","q");bind("#fmin","min");bind("#fmax","max");$("#fc").onchange=e=>{F.county=e.target.value;F.area="";browse()};[["#fa","area"],["#ft","type"],["#fs","sort"]].forEach(([i,k])=>$(i).onchange=e=>{F[k]=e.target.value;browse()});trackSearch()}
let TW;
function setF(k,v){const county=k=="area"&&countyForArea(v)?countyForArea(v):F.county||"Nairobi";F={q:"",county,area:"",type:"",min:"",max:"",feat:[],sort:"new",map:false};if(k)F[k]=k=="feat"?[v]:v;go("browse")}
function tilePhoto(listings,seed){const local=listings.flatMap(l=>l.real||[]),fallback=[...(S.gallery||[]).map(x=>x.src),...S.listings.flatMap(l=>l.real||[])],photos=local.length?local:fallback;return photos.length?photos[Math.random()*photos.length|0]:art(seed,seed%3)}
async function loadPopularAreas(county){if(!county)return;try{const result=await api("/popular-areas?county="+encodeURIComponent(county));S.popularAreas[county]=result.areas;S.featuredAreas[county]=result.featured;if(view==="home"&&$("#hc")&&$("#hc").value===county)renderPopularAreas(county)}catch(e){toast("Could not load popular areas: "+e.message)}}
function renderPopularAreas(county){const el=$("#popular-areas");if(!el)return;const heading=$("#popular-heading"),areas=S.popularAreas[county]||[];if(heading)heading.textContent="Popular areas in "+county;el.innerHTML=areas.length?areas.map(({area,searches},i)=>`<div class="tile" data-photo-area="${esc(area)}" onclick="setF('area','${area}')"><img src="${tilePhoto(S.listings.filter(l=>l.area===area),i+23)}" alt="${esc(area)} homes"><div>${esc(area)}<small>${searches} searches</small></div></div>`).join(""):`<div class="empty">${S.featuredAreas[county]?.length?"No featured areas selected yet.":"Popular areas will appear as people search in "+esc(county)+"."}</div>`}
function trackSearch(){api("/search-events",{method:"POST",json:{county:F.county||"Nairobi",area:F.area||null,type:F.type||null}}).catch(error=>console.error("Search tracking failed:",error.message))}
async function loadAnalytics(days){S.analyticsDays=days;try{S.analytics=await api("/admin/analytics?days="+days);const el=$("#analytics-content");if(el)el.innerHTML=analyticsContent()}catch(e){toast("Could not load analytics: "+e.message)}}
function analyticsContent(){const a=S.analytics;if(!a)return'<div class="empty">Loading analytics…</div>';const p=a.performance,u=a.activity,max=Math.max(1,...a.daily.map(x=>+x.searches)),errorRate=p.requests?Math.round(100*p.errors/p.requests):0,latencyNote=+p.p95_ms>=1000?"Review slow requests; 95th-percentile latency is above one second.":"Request latency is within one second at the 95th percentile.";const summary=`Last ${a.days} days: ${u.users} new users, ${u.listings} listings, ${u.requests} property requests and ${u.searches} searches. ${errorRate}% of API requests returned errors. ${latencyNote}`;return`<div class="ana-summary"><b>Period summary</b><p>${esc(summary)}</p></div><div class="ana-stats"><div><b>${p.requests}</b><span>API requests</span></div><div><b>${p.errors}</b><span>Errors</span></div><div><b>${p.avg_ms} ms</b><span>Average latency</span></div><div><b>${p.p95_ms} ms</b><span>95th percentile</span></div><div><b>${u.users}</b><span>New users</span></div><div><b>${u.listings}</b><span>New listings</span></div><div><b>${u.requests}</b><span>Property requests</span></div><div><b>${u.searches}</b><span>Area searches</span></div><div><b>${KES(a.revenue.total||0)}</b><span>Revenue (${a.revenue.count||0} payments)</span></div></div><h3>Search activity by day</h3><div class="ana-chart">${a.daily.map(x=>`<div title="${esc(String(x.day))}: ${x.searches} searches"><i style="height:${Math.max(3,+x.searches/max*100)}%"></i><small>${String(x.day).slice(5)}</small></div>`).join("")||'<span class="sub">No search activity in this period yet.</span>'}</div><h3>Most searched areas</h3><div class="chips">${a.searches.map(x=>`<span class="chip">${esc(x.county)} · ${esc(x.area)} · ${x.searches}</span>`).join("")||'<span class="sub">No searches recorded yet.</span>'}</div><h3>System health</h3><p class="sub"><span class="dot ${a.database.ok?"ok":"no"}"></span>Database ${a.database.ok?"connected":"unavailable"} · Revenue: ${KES(a.revenue.total||0)} from ${a.revenue.count||0} payments${(a.revenue.byKind||[]).map(k=>` · ${{view_pack:'house views',boost:'boosts',suggest_sub:'subscriptions'}[k.kind]||k.kind}: ${KES(k.total)}`).join('')}.</p>`}
